window.NPC_CHUNK_6 = [{"name":"Galenna Icethorne","cr":5,"xp":1600,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"sorcerer","level":6}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":-1,"ac":10,"ac_touch":9,"ac_flat_footed":9,"ac_mods":"+1 armor, -1 Dex","hp":29,"hd":"6d6+6","hd_value":6,"fort":3,"ref":1,"will":7,"defensive_abilities":["fated +1"],"speed":[{"type":"land","speed":30}],"melee":"mwk dagger +4 (1d4/19-20)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"6/day","spells":[{"spell":"touch of destiny","details":"+3"}]}],"spellsknown_caster_level":6,"spellsknown_concentration":9,"spellsknown":[{"spell_level":3,"spell_slots":3,"spells":[{"spell":"sleet storm"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"blur"},{"spell":"detect thoughts"},{"spell":"invisibility"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"alarm"},{"spell":"charm person"},{"spell":"chill touch"},{"spell":"color spray"},{"spell":"comprehend languages"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"flare"},{"spell":"light"},{"spell":"message"},{"spell":"ray of frost"}]}],"bloodline":"destined","strength":10,"dexterity":8,"constitution":12,"intelligence":14,"wisdom":14,"charisma":17,"baseatk":3,"cmb":3,"cmd":14,"feats":[{"feat":"Alertness"},{"feat":"Combat Casting"},{"feat":"Endurance"},{"feat":"Eschew Materials"},{"feat":"Silent Spell"}],"skills":[{"skill":"Diplomacy","value":9},{"skill":"Knowledge (geography)","value":6},{"skill":"Knowledge (history)","value":8},{"skill":"Knowledge (local)","value":6},{"skill":"Linguistics","value":3},{"skill":"Perception","value":7},{"skill":"Sense Motive","value":10},{"skill":"Spellcraft","value":11},{"skill":"Survival","value":5}],"languages":["Common","Giant","Hallit","Skald"],"sq":["bloodline arcana"],"gear":"bracers of armor +1, masterwork dagger, 173 gp, potion of cure moderate wounds, potion of gaseous form, scroll of dispel magic, scroll of obscuring mist, scroll of tiny hut, wand of magic missile (CL 3rd, 30 charges)","before_combat":"If Galenna is near a civilized area, she presses others into service to assist her in an upcoming battle. No town can deny her access to whatever guard they have, and she has been known to demand that even farmers fight for her. Galenna casts invisibility and enters combat with chill touch when she deems the moment right.","during_combat":"Galenna recognizes fellow spellcasters and attempts to disable them first with her offensive spells and her wand of magic missile. She then casts sleet storm to catch the largest number of enemies in its area, even if this means damaging her allies.","morale":"Galenna is unafraid of death, knowing that her sisters will eventually recover her body and restore her to life, but she prefers to avoid being killed if it is within her power to do so. If things go poorly in a battle, she uses her potion of gaseous form to escape.","source":"NPC Guide"},{"name":"Fadil ibn-Kazar","cr":3,"xp":800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"rogue","level":4}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["human"],"init":7,"ac":16,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+3 armor, +3 Dex","hp":21,"hd":"4d8","hd_value":4,"fort":1,"ref":7,"will":2,"defensive_abilities":["evasion","trap sense +1","uncanny dodge"],"speed":[{"type":"land","speed":30}],"melee":"mwk dagger +7 (1d4-1/19-20)","ranged":"mwk light crossbow +7 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"strength":8,"dexterity":16,"constitution":10,"intelligence":16,"wisdom":12,"charisma":13,"baseatk":3,"cmb":2,"cmd":15,"feats":[{"feat":"Deceitful"},{"feat":"Improved Initiative"},{"feat":"Persuasive"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Appraise","value":10},{"skill":"Bluff","value":10},{"skill":"Diplomacy","value":10},{"skill":"Disable Device","value":10},{"skill":"Disguise","value":10},{"skill":"Intimidate","value":7},{"skill":"Knowledge (geography)","value":5},{"skill":"Knowledge (history)","value":5},{"skill":"Knowledge (local)","value":10},{"skill":"Linguistics","value":10},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":8},{"skill":"Sleight of Hand","value":10},{"skill":"Stealth","value":9}],"languages":["Common","Elven","Gnoll","Gnome","Halfling","Kelish","Osiriani","Varisian"],"sq":["rogue talents (finesse rogue, slow reactions)","trapfinding +2"],"gear":"+1 leather armor, masterwork light crossbow with 20 bolts, masterwork dagger, pieces of various disguises, 560 gp (mostly in the form of pesh, if it is legal to carry), potion of cure light wounds","before_combat":"Fadil prefers to avoid combat whenever possible. If he cannot escape in disguise, he attempts to use his slow reactions ability and flee. He tries diplomacy first if he has even a few seconds to try to talk his opponents out of killing him.","during_combat":"If forced to fight, Fadil tries to feint the opponent who looks physically strongest and then disable him with a sneak attack. Fadil knows he cannot take many direct hits, so he fights defensively whenever attacking.","morale":"Fadil runs at the first opportunity unless it means abandoning his product. He tries his best to negotiate if his pesh is on the line, fleeing only if it becomes apparent that to stay would mean death. He is willing to offer some of his product, information, or services in exchange for his hide.","source":"NPC Guide"},{"name":"Vendlara Alderane","cr":3,"xp":800,"race":"elf","gender":"Female","age_category":"Adult","classes":[{"class":"ranger","level":4}],"alignment":"CG","size":"Medium","type":"humanoid","sub_types":["elf"],"init":3,"senses":["low-light vision"],"ac":19,"ac_touch":14,"ac_flat_footed":15,"ac_mods":"+5 armor, +3 Dex, +1 dodge","hp":26,"hd":"4d10+4","hd_value":4,"fort":4,"ref":7,"will":1,"save_mods":"+2 vs. enchantment","immunities":["sleep"],"speed":[{"type":"land","speed":30}],"melee":"mwk longsword +7 (1d8+3/19-20)","ranged":"mwk composite longbow +8 (1d8+2/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"chaotic outsiders +2"}],"strength":14,"dexterity":17,"constitution":10,"intelligence":11,"wisdom":10,"charisma":14,"baseatk":4,"cmb":6,"cmd":19,"feats":[{"feat":"Dodge"},{"feat":"Endurance"},{"feat":"Persuasive"},{"feat":"Point-Blank Shot"}],"skills":[{"skill":"Acrobatics","value":6},{"skill":"Bluff","value":5},{"skill":"Climb","value":6},{"skill":"Diplomacy","value":4},{"skill":"Intimidate","value":8},{"skill":"Knowledge (nature)","value":6},{"skill":"Perception","value":8},{"skill":"Stealth","value":8},{"skill":"Survival","value":6},{"skill":"Swim","value":8}],"languages":["Common","Elven"],"sq":["elven magic","favored terrain (forest +2)","hunter's bond  (companions)","track +2","weapon familiarity","wild empathy +6"],"gear":"+1 chain shirt, masterwork longsword, masterwork composite longbow (+2 Str) with 20 arrows, 215 gp, tanglefoot bags (4)","before_combat":"Vendlara likes to ambush enemies.","during_combat":"Vendlara prefers to fight from a distance, and from a secure tree branch if possible. She uses her tanglefoot bags against winged or fast opponents to slow them down and prevent pursuit or escape. If her allies are not practiced demon hunters, she uses her hunter's bond ability.","morale":"Vendlara flees if her arrows seem ineffectual, using tanglefoot bags to help her escape.","source":"NPC Guide"},{"name":"Modoru Redgrave","cr":3,"xp":800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"aristocrat","level":1},{"class":"paladin","level":4}],"alignment":"LG","size":"Medium","type":"humanoid","sub_types":["human"],"init":0,"auras":["courage (10 ft.)"],"ac":19,"ac_touch":10,"ac_flat_footed":19,"ac_mods":"+9 armor","hp":40,"hd":"4d10+1d8+14","hd_value":5,"fort":7,"ref":2,"will":8,"defensive_abilities":["divine grace +1"],"immunities":["fear"],"speed":[{"type":"land","speed":30}],"melee":"mwk longsword +8 (1d8+4/19-20)","ranged":"mwk composite longbow +5 (1d8+2/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel positive energy","details":"DC  13, 2d6"},{"type":"smite evil","details":"2/day, +1 attack and AC, +4  damage"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect evil"}]}],"spellsprepared_caster_level":1,"spellsprepared_concentration":2,"spellsprepared":[{"spell_level":1,"spell_slots":1,"spells":[{"spell":"lesser restoration"}]}],"strength":16,"dexterity":10,"constitution":14,"intelligence":10,"wisdom":13,"charisma":12,"baseatk":4,"cmb":7,"cmd":17,"feats":[{"feat":"Animal Affinity"},{"feat":"Extra Lay on Hands"},{"feat":"Mounted Combat"},{"feat":"Trample"}],"skills":[{"skill":"Diplomacy","value":6},{"skill":"Handle Animal","value":9},{"skill":"Heal","value":8},{"skill":"Perception","value":6},{"skill":"Ride","value":5},{"skill":"Sense Motive","value":5}],"languages":["Common"],"sq":["aura of good","lay on hands (2d6, 5/day)","mercy (shaken)"],"gear":"masterwork full plate, masterwork heavy steel shield, masterwork composite longbow (+2 Str) with 20 arrows, masterwork longsword, healer's kit, combat trained heavy horse (Ironring), sunrods (2), 263 gp, holy water (4)","before_combat":"Modoru doesn't use his shield in mounted combat but does keep it on his horse in case he needs to enter single combat.","during_combat":"Modoru attempts to use his warhorse, Ironring, as his primary weapon in combat. He leads with an overrun attack to soften opponents before wheeling around to finish them off. He is willing to dismount but attempts to fight from horseback for as long as is feasible.","morale":"Modoru knows the value of a tactical retreat, but he never leaves combat due to personal injury, only for the good of those around him.","base_statistics":"When using his shield, Modoru's statistics are: Melee mwk longsword +8 (1d8+3/19-20); AC 21, touch 20, flat-footed 21 (+9 armor, +2 shield); Skills Ride +4","source":"NPC Guide"},{"name":"Bjorn Grimsong","cr":7,"xp":3200,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":2},{"class":"fighter","level":6}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":20,"ac_touch":10,"ac_flat_footed":19,"ac_mods":"+7 armor, +1 deflection, +1 Dex, -2 rage, +3 shield","hp":102,"hd":"2d12+6d10+56","hd_value":8,"fort":14,"ref":3,"will":6,"save_mods":"+2 vs. fear","defensive_abilities":["bravery +2","uncanny dodge"],"speed":[{"type":"land","speed":40}],"melee":"+1 battleaxe +15 (1d8+8/x3)","ranged":"mwk shortbow +10 (1d6/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rage","details":"10 rounds/day"},{"type":"rage power","details":"superstition +2"},{"type":"weapon training","details":"axes +1"}],"strength":18,"dexterity":12,"constitution":22,"intelligence":8,"wisdom":10,"charisma":14,"baseatk":8,"cmb":12,"cmb_special":"+14 sunder","cmd":21,"cmd_special":"23 vs. sunder","feats":[{"feat":"Dazzling Display"},{"feat":"Disruptive"},{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Step Up"},{"feat":"Toughness"},{"feat":"Weapon Focus (battleaxe)"},{"feat":"Weapon Specialization (battleaxe)"}],"skills":[{"skill":"Climb","value":10},{"skill":"Heal","value":2},{"skill":"Knowledge (geography)","value":1},{"skill":"Knowledge (nature)","value":3},{"skill":"Perception","value":9},{"skill":"Survival","value":8},{"skill":"Swim","value":8}],"languages":["Common"],"sq":["armor training 1","fast movement"],"gear":"+1 breastplate, +1 heavy wooden shield, +1 battleaxe, masterwork short bow with 20 arrows, ring of protection +1, 363 gp, potion of cure moderate wounds, potion of bull's strength","before_combat":"If Bjorn has a chance to show off his prowess before the fight starts, he uses his Dazzling Display feat to cow enemies. His relative inexperience with battle magic means that he avoids reliance on spellcasters, though he is willing to accept beneficial spells if the opportunity presents itself. If he expects to be outnumbered or fighting a powerful opponent, he drinks his potion of bull's strength in preparation for battle.","during_combat":"Wielding the prince's axe, Bjorn relies on his rage and Power Attack feat to maximize damage. He likes to sunder enemy weapons, and uses his Step Up and Disruptive feats to press the attack against lightly armored enemies and spellcasters.","morale":"Bjorn believes that he has a destiny to fulfill. As such, he doesn't waste his time with fights that don't serve his cause, nor with battles he cannot win. If Bjorn is reduced to 20 or fewer hit points, he retreats. He also retreats from an obviously superior foe. If he is convinced that he is working toward the destruction of the sorcerer, he is implacable and will seek any advantage.","base_statistics":"When not raging, Bjorn's stats are: AC 22, touch 12, flat-footed 21; hp 86; Fort +12, Will +4; Melee +1 battleaxe +13/+8 (1d8+6/x3); Str 14, Con 18; CMB +10; Skills Climb +8, Swim +6","source":"NPC Guide"},{"name":"Thaim","cr":2,"xp":600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"ranger","level":3}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":15,"ac_touch":11,"ac_flat_footed":14,"ac_mods":"+4 armor, +1 Dex","hp":25,"hd":"3d10+9","hd_value":3,"fort":6,"ref":4,"will":1,"speed":[{"type":"land","speed":30}],"melee":"mwk longspear +6 (1d8+3/x3) or mwk shortspear +6 (1d6+2)","ranged":"mwk shortspear +5 (1d6+2) or mwk sling +5 (1d4+2) or javelin +4 (1d6+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"animals +2"}],"strength":14,"dexterity":13,"constitution":17,"intelligence":8,"wisdom":10,"charisma":12,"baseatk":3,"cmb":5,"cmd":16,"feats":[{"feat":"Animal Affinity"},{"feat":"Endurance"},{"feat":"Far Shot"},{"feat":"Mounted Combat"},{"feat":"Point-Blank Shot"},{"feat":"Trample"}],"skills":[{"skill":"Climb","value":4},{"skill":"Handle Animal","value":9},{"skill":"Heal","value":4},{"skill":"Knowledge (nature)","value":5},{"skill":"Perception","value":6},{"skill":"Perform (Dance)","value":2},{"skill":"Ride","value":7},{"skill":"Stealth","value":5},{"skill":"Survival","value":6}],"languages":["Hallit"],"sq":["favored terrain (plains +2)","track +1","wild empathy +4"],"gear":"masterwork hide armor, masterwork heavy wooden shield, javelins (3), masterwork longspear, masterwork shortspear, masterwork sling with 20 stones, medicine bag, pet mammoth, potion of cure light wounds (3)","before_combat":"Thaim thinks like a hunter and tries to arrange the conditions of the battle as if he were hunting an animal, mainly by relying on surprise.","during_combat":"Thaim prefers to fight while riding his mammoth. If he must fight on the ground, he uses his longspear, or shortspear and shield if his enemy is particularly dangerous (AC 17, touch 11, flat-footed 16 [+4 armor, +1 Dex, +2 shield]).","morale":"Although Thaim isn't terribly bright, he understands that his mission to save his tribe will fail if he dies. If brought to 10 hit points or fewer, he flees, directing his mammoth to clear a path if possible.","source":"NPC Guide"},{"name":"Illian Glanadrian","cr":7,"xp":3200,"race":"elf","gender":"Female","age_category":"Adult","classes":[{"class":"assassin","level":3},{"class":"bard","level":5}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["elf"],"init":3,"senses":["low-light vision"],"ac":18,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+5 armor, +3 Dex","hp":27,"hd":"8d8-8","hd_value":8,"fort":2,"ref":10,"will":8,"save_mods":"+1 vs. poison+2 vs. enchantments;  +4 vs. bardic performance, language-dependent, and sonic","defensive_abilities":["uncanny dodge"],"immunities":["sleep"],"speed":[{"type":"land","speed":30}],"melee":"violin bow (improvised) +7 (1d3-1) or +1 dagger +8 (1d4/19-20 plus poison)","ranged":"dagger +7 (1d4-1/19-20 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 15 rounds/day","details":"countersong,  distraction, fascinate [DC 16], inspire competence +2, inspire  courage +2"},{"type":"death attack","details":"DC 15"},{"type":"sneak attack","details":"+2d6"}],"spellsknown_caster_level":5,"spellsknown_concentration":8,"spellsknown":[{"spell_level":2,"spell_slots":3,"spells":[{"spell":"eagle's splendor"},{"spell":"hold person"},{"spell":"silence"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"disguise self"},{"spell":"expeditious retreat"},{"spell":"sleep"},{"spell":"undetectable alignment"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"lullaby"},{"spell":"mage hand"},{"spell":"open/ close"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"strength":8,"dexterity":16,"constitution":8,"intelligence":14,"wisdom":14,"charisma":16,"baseatk":4,"cmb":3,"cmd":16,"feats":[{"feat":"Catch Off-Guard"},{"feat":"Quick Draw"},{"feat":"Run"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Disguise","value":11},{"skill":"Intimidate","value":11},{"skill":"Knowledge (local)","value":12},{"skill":"Perception","value":15},{"skill":"Perform (act)","value":14},{"skill":"Perform (string instruments)","value":14},{"skill":"Sense Motive","value":13},{"skill":"Sleight of Hand","value":14},{"skill":"Stealth","value":14}],"languages":["Common","Celestial","Elven","Sylvan"],"sq":["bardic knowledge +2","elven magic","lore master 1/day","poison use","versatile performance (string instruments)","weapon familiarity"],"gear":"+1 mithral chain shirt, +1 dagger, daggers (2), cloak of resistance +1, jewelry worth 300 gp, large scorpion venom (5), masterwork violin, 350 gp, potion of cure moderate wounds, potions of invisibility (2)","before_combat":"Illian avoids actual combat if at all possible, fleeing confrontations that don't happen on her terms. When she is about to commit murder, she casts eagle's splendor, poisons her daggers, uses fascinate, and finishes with a death attack.","during_combat":"Illian uses hold person, sleep, or her Catch Off-Guard feat to make sneak attacks. She uses silence to prevent her foes from calling for aid, and Bluff and Diplomacy skills if guards respond to the noise.","morale":"If Illian is outnumbered or a victim doesn't succumb to her bardic abilities, she flees immediately.","source":"NPC Guide"},{"name":"Ntanga","cr":3,"xp":800,"race":"sentient ape","gender":"Male","age_category":"Adult","classes":[{"class":"rogue","level":4}],"alignment":"CE","size":"Medium","type":"magical beast","init":3,"senses":["low-light vision","scent"],"ac":19,"ac_touch":14,"ac_flat_footed":15,"ac_mods":"+4 armor, +3 Dex, +1 dodge, +1 natural","hp":45,"hd":"7d8+14","hd_value":7,"fort":8,"ref":10,"will":3,"defensive_abilities":["evasion","trap sense +1","uncanny dodge"],"speed":[{"type":"climb","speed":30},{"type":"land","speed":30}],"melee":"2 slams +8 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"strength":15,"dexterity":16,"constitution":14,"intelligence":13,"wisdom":12,"charisma":8,"baseatk":5,"cmb":7,"cmd":21,"feats":[{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Mobility"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Acrobatics","value":7},{"skill":"Bluff","value":9},{"skill":"Climb","value":16},{"skill":"Disable Device","value":12},{"skill":"Disguise","value":3},{"skill":"Escape Artist","value":12},{"skill":"Knowledge (history)","value":2},{"skill":"Knowledge (nobility)","value":2},{"skill":"Knowledge (religion)","value":2},{"skill":"Linguistics","value":6},{"skill":"Perception","value":12},{"skill":"Perform (dance)","value":3},{"skill":"Sense Motive","value":9},{"skill":"Sleight of Hand","value":9},{"skill":"Stealth","value":11},{"skill":"Swim","value":6}],"languages":["Common","Abyssal","Elven","Osiriani","Polyglot"],"sq":["rogue talent (combat trick, ledge walker)","trapfinding +2"],"gear":"+1 studded leather, chain collar and leash, masterwork thieves' tools, 475 gp, necklace of fireballs (type I; two 3d6 beads remaining)","before_combat":"Ntanga pretends to be a simple animal so potential enemies don't consider him a significant threat.","during_combat":"If Kingstone is present, Ntanga pretends to wait until his \"master\" orders him to fight. He makes use of his climbing and Mobility to find an advantageous position in a battle, using his necklace of fireballs if facing many foes or if he needs to end combat quickly to maintain his cover.","morale":"If Ntanga is brought to 10 hit points or fewer, his behavior depends on what his opponents know. If they believe him to be just an animal, he flees or prostrates himself before them. If they know he is intelligent, he flees or tries to bargain for his life.","source":"NPC Guide"},{"name":"Satha","cr":8,"xp":4800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"evoker","level":9}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human"],"init":5,"ac":14,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+1 armor, +1 deflection, +1 Dex, +1 natural","hp":58,"hd":"9d6+27","hd_value":9,"fort":6,"ref":5,"will":7,"speed":[{"type":"land","speed":30}],"melee":"dagger +3 (1d4-1/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"intense spells"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"elemental wall","details":"12 rounds/day"}]},{"frequency":"7/day","spells":[{"spell":"force missile"}]}],"spellsprepared_caster_level":9,"spellsprepared_concentration":13,"spellsprepared":[{"spell_level":5,"spell_slots":2,"spells":[{"spell":"cone of cold"},{"spell":"elemental body II"}]},{"spell_level":4,"spell_slots":3,"spells":[{"spell":"fire shield"},{"spell":"shout"},{"spell":"wall of fire"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"fireball"},{"spell":"fly"},{"spell":"halt undead"},{"spell":"lightning bolt"},{"spell":"vampiric touch"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"bear's endurance"},{"spell":"command undead"},{"spell":"darkvision"},{"spell":"false life"},{"spell":"flaming sphere"},{"spell":"rope trick"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"burning hands","count":2},{"spell":"floating disk"},{"spell":"magic missile","count":2},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"disrupt undead"},{"spell":"light"},{"spell":"mage hand"},{"spell":"read magic"}]}],"prohibited_schools":"Enchantment, Illusion","strength":8,"dexterity":13,"constitution":14,"intelligence":19,"wisdom":10,"charisma":12,"baseatk":4,"cmb":3,"cmd":15,"feats":[{"feat":"Arcane Strike"},{"feat":"Brew Potion"},{"feat":"Combat Casting"},{"feat":"Greater Spell Focus (evocation)"},{"feat":"Improved Initiative"},{"feat":"Scribe Scroll"},{"feat":"Spell Focus (evocation)"},{"feat":"Toughness"}],"skills":[{"skill":"Appraise","value":12},{"skill":"Craft (alchemy)","value":14},{"skill":"Fly","value":11},{"skill":"Intimidate","value":2},{"skill":"Knowledge (arcana)","value":16},{"skill":"Knowledge (geography)","value":9},{"skill":"Knowledge (religion)","value":11},{"skill":"Linguistics","value":8},{"skill":"Perception","value":9},{"skill":"Profession (scribe)","value":4},{"skill":"Ride","value":2},{"skill":"Sense Motive","value":7},{"skill":"Spellcraft","value":16},{"skill":"Use Magic Device","value":10}],"languages":["Common","Draconic","Gnome","Kelish","Osiriani","Vudrani"],"sq":["arcane bond (ring of protection)"],"gear":"amulet of natural armor +1, bracers of armor +1, cloak of resistance +1, ring of protection +1, 610 gp, potions of bear's endurance, cure moderate wounds, cure serious wounds, darkvision, invisibility, protection from arrows, protection from energy (fire), resist energy (cold), resist energy (fire), and water breathing; scrolls of alter self, cone of cold, and expeditious retreat","before_combat":"Satha casts false life on himself every day. Given warning about the nature of his opponents, Satha drinks potions of protection from energy and resist energy. If he expects flying enemies or needs to maneuver quickly, he casts fly. If he anticipates the need to flee, he casts rope trick in a hidden place to give him a place to retreat to.","during_combat":"Satha tries to deal as much damage as possible at the start of combat in order to kill as many weak opponents as he can. Depending on the nature of his opponents, he may cast fire shield or shield, or use a defensive scroll. If battling undead, he either tries to kill them with brute force or disables the leader with command undead or halt undead to give himself time to destroy enemy minions. He likes to use his elemental wall ability to divide the battlefield to his advantage.","morale":"Satha has died once and doesn't want to experience that again; if brought to 20 hit points or fewer, he flees, using elemental wall, expeditious retreat, fly, invisibility, or rope trick as needed.","source":"NPC Guide"},{"name":"Alviana Shadowsworn","cr":5,"xp":1600,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"druid of Zon-Kuthon","level":6}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":16,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+5 armor, +1 Dex","hp":27,"hd":"6d8","hd_value":6,"fort":5,"ref":3,"will":9,"defensive_abilities":["resist nature's lure"],"speed":[{"type":"land","speed":30}],"melee":"scimitar +3 (1d6-1/18-20)","ranged":"sling +5 (1d4-1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"wild shape","details":"2/day"}],"spellsprepared_caster_level":6,"spellsprepared_concentration":10,"spellsprepared":[{"spell_level":3,"spell_slots":3,"spells":[{"spell":"call lightning"},{"spell":"invisibility"},{"spell":"poison"}]},{"spell_level":2,"spell_slots":4,"spells":[{"spell":"barkskin"},{"spell":"chill touch"},{"spell":"gust of wind"},{"spell":"summon swarm"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"cure light wounds"},{"spell":"entangle"},{"spell":"magic stone"},{"spell":"touch of fatigue"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"disrupt undead"},{"spell":"guidance"},{"spell":"ray of frost"}]}],"strength":8,"dexterity":12,"constitution":10,"intelligence":14,"wisdom":18,"charisma":13,"baseatk":4,"cmb":3,"cmd":14,"feats":[{"feat":"Alertness"},{"feat":"Augment Summoning"},{"feat":"Natural Spell"},{"feat":"Shade of the Uskwood"}],"skills":[{"skill":"Bluff","value":3},{"skill":"Diplomacy","value":4},{"skill":"Disguise","value":3},{"skill":"Fly","value":5},{"skill":"Handle Animal","value":10},{"skill":"Heal","value":10},{"skill":"Knowledge (arcana)","value":3},{"skill":"Knowledge (dungeoneering)","value":3},{"skill":"Knowledge (geography)","value":6},{"skill":"Knowledge (history)","value":4},{"skill":"Knowledge (local)","value":3},{"skill":"Knowledge (nature)","value":11},{"skill":"Knowledge (nobility)","value":3},{"skill":"Knowledge (religion)","value":5},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":8},{"skill":"Stealth","value":1},{"skill":"Survival","value":15},{"skill":"Swim","value":1}],"languages":["Common","Druidic","Shadowtongue","Varisian"],"sq":["nature bond (owl companion named Sootsable)","nature sense","trackless step","wild empathy +7","woodland stride"],"special_abilities":[{"type":"Feats","details":"Alviana's Shade of the Uskwood feat is only available to a sect of albino druids from Nidal allied with the church of Zon-Kuthon; this feat adds unusual spells to the druid's spell list, removes all fire spells from it, and requires an Umbrae-Token (an effigy made of hair, twigs, and blood that counts as an unholy symbol). See page 111 of the Pathfinder Chronicles Campaign Setting."}],"gear":"+1 hide armor, scimitar, sling with 10 bullets, pearl of power (1st level), Umbrae-Token, 120 gp, potion of cure serious wounds, scroll of ice storm, wand of chill metal (10 charges), goodberries (8)","before_combat":"Alviana summons animals (preferring bats and snakes) just before battle to outnumber and overwhelm her opponents.","during_combat":"Alviana prefers to stay out of direct combat, hiding either invisibly or in animal form, summoning creatures to eliminate foes.","morale":"Alviana flees if in serious danger, preferably by becoming invisible or using wild shape to become a bat.","source":"NPC Guide"},{"name":"Tal Taval","cr":9,"xp":6400,"race":"human","gender":"Male","age_category":"Old","classes":[{"class":"ranger","level":4},{"class":"rogue","level":6}],"alignment":"LG","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":20,"ac_touch":14,"ac_flat_footed":17,"ac_mods":"+5 armor, +1 deflection, +2 Dex, +1 dodge, +1 natural","hp":49,"hd":"4d10+6d8","hd_value":10,"fort":9,"ref":12,"will":7,"defensive_abilities":["evasion","trap sense +2","uncanny dodge"],"speed":[{"type":"land","speed":35}],"melee":"mwk short sword +7 (1d6-2/19-20)","ranged":"+1 longbow +11 (1d8-1/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"goblinoids +2"},{"type":"sneak attack","details":"+3d6"}],"spellsprepared_caster_level":1,"spellsprepared_concentration":4,"spellsprepared":[{"spell_level":1,"spell_slots":1,"spells":[{"spell":"jump"}]}],"strength":6,"dexterity":15,"constitution":10,"intelligence":15,"wisdom":16,"charisma":12,"baseatk":8,"cmb":6,"cmd":20,"feats":[{"feat":"Deadly Aim"},{"feat":"Dodge"},{"feat":"Endurance"},{"feat":"Fleet"},{"feat":"Great Fortitude"},{"feat":"Mobility"},{"feat":"Point-Blank Shot"},{"feat":"Shot on the Run"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Bluff","value":14},{"skill":"Climb","value":10},{"skill":"Knowledge (geography)","value":15},{"skill":"Knowledge (nature)","value":15},{"skill":"Perception","value":16},{"skill":"Perform (oratory)","value":14},{"skill":"Sense Motive","value":16},{"skill":"Stealth","value":14},{"skill":"Survival","value":16},{"skill":"Swim","value":10}],"languages":["Common","Elven","Orc"],"sq":["favored terrain (water +2)","hunter's bond (dog animal  companion named Blue)","rogue talents (fast stealth,  resiliency, stand up)","track +2","trapfinding +3","wild empathy +7"],"gear":"+1 chain shirt, +1 longbow with 20 arrows, masterwork short sword, amulet of natural armor +1, boots of the winterlands, cloak of resistance +1, ring of protection +1, 450 gp, elixir of swimming, feather tokens (anchor, fan, swan)","before_combat":"If Tal expects combat, he casts jump on himself so that he can easily leap from his barge to shore or vice versa. If he thinks he's coming into dangerous territory, he uses his fast stealth rogue ability to sneak up on enemies so that he can fire arrows from concealment.","during_combat":"Tal prefers to fight from his barge, forcing opponents to swim to him. He relies on his speed and mobility to stay out of reach of his enemies. If forced into melee combat, he uses his dog (named \"Blue\") to flank so he can make sneak attacks.","morale":"Tal knows when it is time to run and isn't above stranding foes on his barge with his anchor feather token, leaping away under the effects of his jump spell, and using his swan boat feather token to create another craft to escape in. But when defending innocents or fighting evil, he gives no quarter and never quits.","source":"NPC Guide"},{"name":"Rupert Raim","cr":5,"xp":1600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":6}],"alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":22,"ac_touch":11,"ac_flat_footed":11,"ac_mods":"+8 armor, +1 Dex, +3 shield","hp":51,"hd":"6d10+18","hd_value":6,"fort":7,"ref":3,"will":4,"save_mods":"+2 vs. fear","defensive_abilities":["bravery +2"],"speed":[{"type":"land","speed":20}],"melee":"+1 longsword with godslayer blessing +12 (1d8+7/19-20) or dagger +9 (1d4+3/19-20)","ranged":"longbow +7 (1d8/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"weapon training","details":"heavy blades +1"}],"strength":16,"dexterity":12,"constitution":15,"intelligence":10,"wisdom":14,"charisma":8,"baseatk":6,"cmb":9,"cmd":20,"feats":[{"feat":"Cleave"},{"feat":"Godless Healing"},{"feat":"Persuasive"},{"feat":"Power Attack"},{"feat":"Shield Focus"},{"feat":"Weapon Focus (longsword)"},{"feat":"Weapon Specialization (longsword)"}],"skills":[{"skill":"Diplomacy","value":2},{"skill":"Heal","value":4},{"skill":"Intimidate","value":6},{"skill":"Knowledge (religion)","value":3},{"skill":"Perception","value":7},{"skill":"Sense Motive","value":7}],"languages":["Common"],"sq":["armor training 1"],"special_abilities":[{"type":"Feats","details":"To compensate for their lack of divine healing, the people of Rahadoum have developed the Godless Healing feat, a specialized technique to ignore injury. Once per day, when Captain Raim is at 25 hit points or fewer, he can make a DC 10 Fortitude save as a move action to heal 1 hit point per level (minimum 3). See page 123 of the Pathfinder Chronicles Campaign Setting."}],"gear":"half-plate, heavy steel shield, +1 longsword with godslayer blessing, dagger, longbow with 20 arrows, 63 gp","before_combat":"Unless under immediate threat, Captain Raim takes his time to study and parley with opponents. However, he rarely gives enemy divine casters a chance to escape.","during_combat":"Captain Raim concentrates his attacks on divine casters. Once he defeats them, he offers a truce to any surviving foes. He often pretends to be a dumb brute to mislead opponents.","morale":"Knowing that if killed he doesn't have the luxury of a divine resurrection, Captain Raim surrenders and lives rather than fighting to the death, though it galls him greatly to be humbled by a religious opponent.","source":"NPC Guide"},{"name":"Huodatha","cr":3,"xp":800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":4}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":13,"ac_touch":10,"ac_flat_footed":11,"ac_mods":"+3 armor, +1 Dex, +1 dodge, -2 rage","hp":46,"hd":"4d12+20","hd_value":4,"fort":9,"ref":2,"will":3,"defensive_abilities":["trap sense +1","uncanny dodge"],"speed":[{"type":"land","speed":40}],"melee":"mwk greatclub +10 (1d10+7) or improvised club +9 (1d6+5)","ranged":"improvised club +5 (1d6+5)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rage","details":"19 rounds/day"},{"type":"rage powers","details":"intimidating glare, roused anger"}],"strength":20,"dexterity":13,"constitution":20,"intelligence":8,"wisdom":10,"charisma":12,"baseatk":4,"cmb":9,"cmd":19,"feats":[{"feat":"Catch Off-Guard"},{"feat":"Dodge"},{"feat":"Extra Rage"}],"skills":[{"skill":"Acrobatics","value":5,"special":"+4 jump"},{"skill":"Climb","value":9},{"skill":"Intimidate","value":8},{"skill":"Knowledge (local)","value":0},{"skill":"Knowledge (religion)","value":0},{"skill":"Linguistics","value":0},{"skill":"Perception","value":7},{"skill":"Ride","value":7},{"skill":"Survival","value":5},{"skill":"Swim","value":10}],"languages":["Common","Hallit"],"sq":["fast movement"],"gear":"masterwork studded leather, masterwork greatclub, iron mask, 920 gp, potions of cure moderate wounds (2)","morale":"Huodatha retreats if his non-raging hit point total reaches 5.","base_statistics":"When not raging, Huodatha's statistics are: AC 15, touch 12, flat-footed 13; Fort +7, Ref +2, Will +1; hp 38; Melee mwk greatclub +8 (1d10+4) or improvised club +7 (1d6+3); Ranged improvised club +7 (1d6+3); Str 16, Con 16; CMB +7; Skills Climb +7, Swim +8.","source":"NPC Guide"},{"name":"Dimata Sirathini","cr":4,"xp":1200,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"ranger","level":5}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human"],"init":4,"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+4 armor, +4 Dex","hp":27,"hd":"5d10","hd_value":5,"fort":4,"ref":8,"will":5,"speed":[{"type":"land","speed":30}],"melee":"mwk scimitar +9 (1d6+2/18-20)","ranged":"mwk light crossbow +10 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"animals +4, magical beasts +2"}],"spellsprepared_caster_level":2,"spellsprepared_concentration":4,"spellsprepared":[{"spell_level":1,"spell_slots":2,"spells":[{"spell":"entangle"},{"spell":"longstrider"}]}],"strength":15,"dexterity":18,"constitution":10,"intelligence":8,"wisdom":14,"charisma":12,"baseatk":5,"cmb":7,"cmd":21,"feats":[{"feat":"Endurance"},{"feat":"Iron Will"},{"feat":"Point-Blank Shot"},{"feat":"Rapid Reload"},{"feat":"Self-Sufficient"},{"feat":"Weapon Focus (scimitar)"}],"skills":[{"skill":"Handle Animal","value":9},{"skill":"Heal","value":10},{"skill":"Intimidate","value":9},{"skill":"Knowledge (geography)","value":7},{"skill":"Linguistics","value":0},{"skill":"Perception","value":10},{"skill":"Stealth","value":12},{"skill":"Survival","value":12},{"skill":"Swim","value":6}],"languages":["Common","Polyglot"],"sq":["favored terrain (jungle +2)","hunter's bond (companions)","track +2","wild empathy+6"],"gear":"+1 studded leather, masterwork light crossbow with 20 bolts, masterwork scimitar, 310 gp, potions of cure moderate wounds (2), elixir of hiding (2), elixir of swimming, Kaava musk (Sargavan \"goop,\")","before_combat":"Dimata readies her crossbow and looks for a defensible position, preferring high ground and deadfalls or other terrain that serves as a barricade. If necessary, she uses her Kaava musk to attract predators to the site of an ambush.","during_combat":"Dimata prefers to stay at range and force enemies to approach her, preferably over treacherous ground. Once her enemies close in, she switches to her scimitar and first tries to eliminate anyone she sees casting spells.","morale":"Dimata is brave but not foolhardy. She tries to flee if greatly outnumbered or obviously outmatched. She uses her knowledge of the jungle to mislead pursuers and hide herself. If there seems to be no other option, she may try to surrender but is more likely to fight to the death than allow herself to be executed by bloodthirsty enemies.","source":"NPC Guide"},{"name":"Jaren the Jinx","cr":5,"xp":1600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":2},{"class":"rogue","level":4}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human"],"init":7,"ac":17,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+3 armor, +3 Dex, +1 dodge","hp":35,"hd":"2d10+4d8+6","hd_value":6,"fort":5,"ref":7,"will":1,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1","evasion","trap sense +1","uncanny dodge"],"weaknesses":["rotting curse"],"speed":[{"type":"land","speed":30}],"melee":"+1 short sword +9 (1d6+2/19-20)","ranged":"mwk light crossbow +9 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"jinx"},{"type":"sneak attack","details":"+2d6"}],"strength":13,"dexterity":16,"constitution":12,"intelligence":10,"wisdom":10,"charisma":14,"baseatk":5,"cmb":6,"cmd":20,"feats":[{"feat":"Acrobatic"},{"feat":"Athletic"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Bluff","value":10},{"skill":"Climb","value":11},{"skill":"Diplomacy","value":10},{"skill":"Disable Device","value":7},{"skill":"Escape Artist","value":10},{"skill":"Knowledge (geography)","value":3},{"skill":"Knowledge (local)","value":4},{"skill":"Perception","value":9},{"skill":"Profession (sailor)","value":5},{"skill":"Sense Motive","value":9},{"skill":"Sleight of Hand","value":10},{"skill":"Swim","value":7},{"skill":"Use Magic Device","value":6}],"languages":["Common"],"sq":["rogue talents (resiliency, stand up)","trapfinding +2"],"special_abilities":[{"type":"Jinx","kind":"Su","details":"Any creature within 10 ft. of Jaren who confirms a critical hit actually misses as if rolling a 1. Jaren has no control over who this affects or when it happens."},{"type":"Rotting Curse","kind":"Su","details":"Jaren suffers from a rotting curse which afflicts him as mummy rot, but only when within 100 ft. of Deadeye, Jessa, Nightscale, or Okonkwo."}],"gear":"+1 leather armor, +1 short sword, masterwork light crossbow with 20 bolts, 535 gp, potion of cure moderate wounds","before_combat":"Jaren tries to fight from higher ground, such as his ship's rigging or crow's nest, allowing him to sneak attack anyone climbing.","during_combat":"Jaren uses Mobility to avoid being flanked and to draw opponents near his pirate allies.","morale":"Jaren loves his life of adventure and flees combat if he believes he'll be killed, jumping off his ship and swimming to safety if necessary.","source":"NPC Guide"},{"name":"Lord Achimair","cr":6,"xp":2400,"race":"sahuagin","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":4}],"alignment":"NE","size":"Medium","type":"monstrous humanoid","sub_types":["aquatic"],"init":2,"senses":["blindsense 30 ft.","darkvision 60 ft."],"ac":16,"ac_touch":10,"ac_flat_footed":14,"ac_mods":"+1 armor, +2 Dex, +5 natural, -2 rage","hp":77,"hd":"2d10+4d12+42","hd_value":6,"fort":13,"ref":6,"will":8,"defensive_abilities":["trap sense +1","uncanny dodge"],"weaknesses":["light blindness"],"speed":[{"type":"land","speed":40},{"type":"swim","speed":60}],"melee":"2 claws +13 (1d4+6), bite +12 (1d4+6)","ranged":"mwk heavy crossbow +8 (1d10/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood frenzy"},{"type":"rage","details":"15 rounds/day"},{"type":"rage  powers","details":"no escape, renewed vigor [1d8+6 hit points]"}],"strength":22,"dexterity":15,"constitution":24,"intelligence":12,"wisdom":14,"charisma":8,"baseatk":6,"cmb":12,"cmd":22,"feats":[{"feat":"Great Fortitude"},{"feat":"Intimidating Prowess"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Acrobatics","value":7},{"skill":"Handle Animal","value":9},{"skill":"Intimidate","value":13},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":4},{"skill":"Stealth","value":13},{"skill":"Survival","value":11},{"skill":"Swim","value":31}],"languages":["Aquan","Common; speak with sharks"],"sq":["fast movement"],"gear":"bracers of armor +1, masterwork heavy crossbow with 14 bolts and +1 shock bolts (4), 136 gp, potion of cure moderate wounds, potion of protection from arrows","before_combat":"Lord Achimair uses water as cover while preparing to use his crossbow, then drinks a potion and moves into melee range.","during_combat":"Lord Achimair uses his blood frenzy in conjunction with rage.","morale":"Lord Achimair believes he is unkillable by humanoids and fights to the death. If his opponents include a creature of at least Large size, he flees when his non-raging hit points reach 10 or fewer.","base_statistics":"When not raging, Lord Achimair has the following statistics: AC 18, touch 12, flat-footed 16; hp 65; Fort +11, Will +6; Melee +2 claws +11 (1d4+4), bite +10 (1d4+4); Str 18, Con 20; CMB +10; Skills Intimidate +11","source":"NPC Guide, Pathfinder RPG Bestiary 239"},{"name":"Adelle Duran","cr":7,"xp":3200,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":8}],"alignment":"CG","size":"Medium","type":"humanoid","sub_types":["human"],"init":8,"ac":23,"ac_touch":16,"ac_flat_footed":18,"ac_mods":"+5 armor, +1 deflection, +4 Dex, +1 dodge, +2 shield","hp":52,"hd":"8d10+8","hd_value":8,"fort":7,"ref":6,"will":1,"save_mods":"+2 vs. fear","defensive_abilities":["bravery +2"],"speed":[{"type":"land","speed":30}],"melee":"+1 falcata +10 (1d8+3/19-20/x3)","ranged":"light crossbow +12 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"weapon training","details":"light blades +1"}],"strength":10,"dexterity":18,"constitution":12,"intelligence":14,"wisdom":8,"charisma":13,"baseatk":8,"cmb":8,"cmb_special":"+10 disarm","cmd":24,"cmd_special":"26 vs. disarm","feats":[{"feat":"Combat Expertise"},{"feat":"Dodge"},{"feat":"Exotic Weapon Proficiency (falcata)"},{"feat":"Improved Disarm"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Taldan Duelist"},{"feat":"Weapon Focus (falcata)"},{"feat":"Weapon Specialization (falcata)"}],"skills":[{"skill":"Acrobatics","value":17},{"skill":"Bluff","value":9},{"skill":"Escape Artist","value":13},{"skill":"Knowledge (history)","value":3},{"skill":"Knowledge (local)","value":3},{"skill":"Knowledge (nobility)","value":5},{"skill":"Perception","value":10},{"skill":"Perform (Dance)","value":13},{"skill":"Sense Motive","value":10},{"skill":"Swim","value":4}],"languages":["Common","Elven","Kelish"],"sq":["armor training 2"],"special_abilities":[{"type":"Feats","details":"Adelle is skilled the art of fighting with the falcata (a type of Taldan sword) and buckler. When using this fighting style, her buckler's shield bonus increases by 1 and she gains a +2 bonus on Acrobatics checks. See page 137 of the Pathfinder Chronicles Campaign Setting."}],"gear":"+1 mithral chain shirt, masterwork buckler, +1 falcata (Pathfinder Chronicles Campaign Setting 208), light crossbow with 10 bolts, ring of protection +1, 120 gp, potions of cure moderate wounds (3)","during_combat":"Adelle relies on her Combat Expertise feat to increase her Armor Class (-2 to attacks, +2 dodge to AC). With her Improved Disarm feat she disarms and taunts armed opponents, suggesting they surrender.","morale":"Adelle has no fear of death. Rather, the only thing she fears is boredom. Adelle will not withdraw against a clearly superior foe, but she may disengage if her opponent is obviously unable to best her and presents no interesting challenges.","source":"NPC Guide"},{"name":"Tpannon","cr":4,"xp":1200,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"ranger","level":5}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["human"],"init":4,"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+4 armor, +4 Dex","hp":37,"hd":"5d10+10","hd_value":5,"fort":6,"ref":8,"will":2,"resists":["fire 5"],"speed":[{"type":"land","speed":30}],"melee":"longsword +6 (1d8+1/19-20)","ranged":"mwk longbow +11 (1d8/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"humans +4,  animals +2"}],"spellsprepared_caster_level":2,"spellsprepared_concentration":3,"spellsprepared":[{"spell_level":1,"spell_slots":2,"spells":[{"spell":"entangle"},{"spell":"summon nature's ally I"}]}],"strength":13,"dexterity":18,"constitution":14,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":5,"cmb":6,"cmd":20,"feats":[{"feat":"Desert Dweller"},{"feat":"Endurance"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"},{"feat":"Weapon Focus (longbow)"}],"skills":[{"skill":"Bluff","value":2},{"skill":"Climb","value":5},{"skill":"Diplomacy","value":1},{"skill":"Disguise","value":3},{"skill":"Handle Animal","value":6},{"skill":"Knowledge (geography)","value":5},{"skill":"Knowledge (history)","value":2},{"skill":"Knowledge (local)","value":2},{"skill":"Linguistics","value":2},{"skill":"Perception","value":9},{"skill":"Ride","value":10},{"skill":"Stealth","value":12},{"skill":"Survival","value":9}],"languages":["Common","Osiriani","Polyglot"],"sq":["favored terrain (desert +2)","hunter's bond (companions)","track +2","wild empathy +4"],"special_abilities":[{"type":"Feats","details":"Tpannon has the Desert Dweller feat, which grants him fire resistance 5 against effects that deal 5 or fewer points of fire damage (attacks that deal 6 or more points of fire damage affect him normally). He has a +4 bonus on checks made to avoid starvation or thirst and on Fortitude saves to avoid nonlethal damage from hot environments (this is in addition to the benefits of the Endurance feat). See page 139 of the Pathfinder Chronicles Campaign Setting."}],"gear":"+1 studded leather, masterwork longbow with 20 arrows, longsword, hat of disguise, unguent of timelessness (2), 125 gp","before_combat":"Tpannon affects a jovial demeanor and keeps targets distracted while his troops deploy. He may summon an ally to help distract or flank opponents.","during_combat":"Tpannon prefers to stay out of melee, not wanting to reveal that he's not as skilled a swordsman as the tales about him suggest. In keeping with his reputation as an excellent strategist, he normally uses his hunter's bond ability to advise his allies when battling humans or dangerous animals.","morale":"Tpannon flees if in serious danger, knowing he can always get more followers by relying on his extensive reputation.","source":"NPC Guide"},{"name":"Esme Currindon","cr":4,"xp":1200,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"aristocrat","level":3},{"class":"sorcerer","level":3}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":11,"ac_touch":11,"ac_flat_footed":10,"ac_mods":"+1 Dex","hp":30,"hd":"6d8+6","hd_value":6,"fort":3,"ref":5,"will":6,"defensive_abilities":["fated +1"],"speed":[{"type":"land","speed":30}],"melee":"unarmed strike +2 (1d3-1 nonlethal)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"8/day","spells":[{"spell":"touch of destiny"}]}],"spellsknown_caster_level":3,"spellsknown_concentration":8,"spellsknown":[{"spell_level":1,"spell_slots":5,"spells":[{"spell":"alarm"},{"spell":"charm person"},{"spell":"hypnotism"},{"spell":"unseen servant"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"ghost sound"},{"spell":"read magic"},{"spell":"touch of fatigue"}]}],"bloodline":"destined","strength":8,"dexterity":13,"constitution":12,"intelligence":14,"wisdom":10,"charisma":20,"baseatk":3,"cmb":2,"cmd":13,"feats":[{"feat":"Alertness"},{"feat":"Eschew Materials"},{"feat":"Lightning Reflexes"},{"feat":"Persuasive"},{"feat":"Spell Focus (enchantment)"}],"skills":[{"skill":"Appraise","value":10},{"skill":"Bluff","value":11},{"skill":"Diplomacy","value":13},{"skill":"Intimidate","value":13},{"skill":"Knowledge (history)","value":7},{"skill":"Knowledge (local)","value":7},{"skill":"Knowledge (nobility)","value":7},{"skill":"Linguistics","value":7},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":9},{"skill":"Spellcraft","value":7}],"languages":["Common","Draconic","Elven","Skald","Varisian"],"sq":["bloodline arcana"],"gear":"headband of alluring charisma +2, noble's outfit, 500 gp","during_combat":"Esme is a poor combatant. If there is no one to protect her, she attempts to charm a likely protector and then flees combat, using unseen servant to close doors and move obstacles into the path of pursuers.","morale":"Esme quickly flees or gracefully surrenders if she believes she would be killed. She isn't frightened by battle; she just understands that she has no aptitude for it.","source":"NPC Guide"},{"name":"Cordeliza Parasca","cr":3,"xp":800,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"bard","level":4}],"alignment":"CG","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":13,"ac_touch":12,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 natural","hp":21,"hd":"4d8","hd_value":4,"fort":1,"ref":6,"will":6,"save_mods":"+4 vs. bardic performance, language-dependent,  and sonic","speed":[{"type":"land","speed":30}],"melee":"quarterstaff +2 (1d6-1)","ranged":"sling +5 (1d4-1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 19  rounds/day","details":"countersong, distraction,  fascinate [DC 15], inspire competence +2,  inspire courage +1"}],"spellsknown_caster_level":4,"spellsknown_concentration":7,"spellsknown":[{"spell_level":2,"spell_slots":2,"spells":[{"spell":"animal messenger"},{"spell":"pyrotechnics"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"alarm"},{"spell":"charm person"},{"spell":"hideous laughter"},{"spell":"sleep"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"flare"},{"spell":"ghost sound"},{"spell":"message"},{"spell":"prestidigitation"}]}],"strength":8,"dexterity":14,"constitution":10,"intelligence":12,"wisdom":14,"charisma":17,"baseatk":3,"cmb":2,"cmd":14,"feats":[{"feat":"Brew Potion"},{"feat":"Extra Performance"},{"feat":"Skill Focus (Perform sing)"}],"skills":[{"skill":"Appraise","value":6},{"skill":"Bluff","value":10},{"skill":"Diplomacy","value":8},{"skill":"Knowledge (arcana)","value":8},{"skill":"Knowledge (history)","value":8},{"skill":"Knowledge (local)","value":8},{"skill":"Perform (dance)","value":8},{"skill":"Perform (oratory)","value":8},{"skill":"Perform (sing)","value":13},{"skill":"Sense Motive","value":8},{"skill":"Sleight of Hand","value":9},{"skill":"Spellcraft","value":6}],"languages":["Common","Draconic","Varisian"],"sq":["bardic knowledge +2","versatile performance (sing)","well-versed"],"gear":"amulet of natural armor +1, Harrow deck, pocketed scarf, 250 sp, potion of invisibility, wand of cure light wounds (5 charges)","before_combat":"Cordeliza isn't a fighter. She calls for help at the first hint of danger. When possible, she tries to head off an impending battle by using her social skills or casting charm person.","during_combat":"Cordeliza screams for her family, local guards, or anyone in the area who might be able to help her. She uses pyrotechnics to cover an escape attempt and hideous laughter and sleep to disable her opponents.","morale":"Time spent gazing into the great beyond has left Cordeliza with a certain calmness about death. However, she has no wish to die just yet and tries everything at her disposal to flee when in danger. She bargains her services or possessions for her life but dies rather than betray her family.","source":"NPC Guide"}];
